style.css:
@-moz-document domain("roblox.com") {
/* 1. THE WALLPAPER */
    html, body {
        background-image: url("https://i.imgur.com/nKp1uLW.jpeg") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
    }

    /* 2. FORCE TRANSPARENCY ON ALL LAYERS */
    #wrap, #container-main, .content, .main-content, .container-main,
    .dark-theme, .light-theme, .rbx-main-content, .section-content,
    .home-header, .game-card-container, .item-card-container, .section,
    .standard-panel, .mcl-container, #GamesListsContainer > div,
    .game-main-content, .tab-container, .tab-content, .rbx-tabs-horizontal,
    .stack, .card-with-game-launch, .container-list, .panel-body,
    .place-container, .background-main-view {
        background-color: transparent !important;
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }

    /* 3. NEW PINK FONT COLOR (#ff99c4) */
    /* This targets titles, labels, links, and general text */
    .text-label, .text-title, .h1, .h2, .h3, .h4, .h5, .h6,
    .text-name, .text-robux, .text-link, a, 
    .game-card-name, .item-card-name, .group-card-name,
    .home-header h1, .section-title h2,
    .rbx-tab-heading span, .text-emphasis,
    .font-header-1, .font-header-2, .font-caption-header,
    .navbar-search-input, .text-footer-nav {
        color: #ff99c4 !important;
        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5) !important; /* Added shadow for better readability on light flowers */
    }

    /* 4. READABILITY OVERLAY */
    .content, .container-main, #container-main {
        background-color: rgba(0, 0, 0, 0.3) !important;
        border-radius: 15px !important;
        padding: 15px !important;
    }

    /* 5. PINK HEADER & SIDEBAR */
    #header, .rbx-header {
        background-color: #ffe8ee !important;
    }

    #navigation, .rbx-left-col {
        background-color: rgba(254, 212, 224, 0.95) !important;
    }

    /* 6. BUTTONS & ACCENTS */
    .rbx-btn-primary-lg, .rbx-btn-secondary-xs, .rbx-highlight {
        background-color: #ffe8ee !important;
        border-color: #ffe8ee !important;
        color: #ff99c4 !important; /* Matching pink for button text */
    }

    /* 7. HIDE ADS */
    #TopAbpContainer, .ad, .ad-annotations, .rbx-nav-sponsor {
        display: none !important;
    }
}
